ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| case {
    ImageFileName=/\\vssadmin\.exe$/i | regex("delete\\s+shadows", field=CommandLine) | Technique := "VSS_DELETE" ;
    ImageFileName=/\\wmic\.exe$/i | regex("shadowcopy\\s+delete", field=CommandLine) | Technique := "VSS_DELETE" ;
    ImageFileName=/\\wevtutil\.exe$/i | regex("\\s(cl|clear-log)\\s", field=CommandLine) | Technique := "LOG_CLEAR" ;
    ImageFileName=/\\bcdedit\.exe$/i | regex("recoveryenabled\\s+no|bootstatuspolicy\\s+ignoreallfailures", field=CommandLine) | Technique := "RECOVERY_DISABLE" ;
    ImageFileName=/\\sdelete(64)?\.exe$/i | Technique := "MASS_WIPE" ;
    ImageFileName=/\\cipher\.exe$/i | regex("/w:", field=CommandLine) | Technique := "MASS_WIPE" ;
    ImageFileName=/\\fsutil\.exe$/i | regex("usn\\s+deletejournal", field=CommandLine) | Technique := "MASS_WIPE" ;
  }
| NOT UserName=/\\$$/
| bucket(span=5m, field=@timestamp, function=groupBy([aid, ComputerName, UserName], function={ collect([Technique, CommandLine]) | DistinctTechniques := count(field=Technique, distinct=true) }))
| DistinctTechniques >= 2
| sort(field=@timestamp, order=desc)
